import{_ as e,c as o,o as s,a3 as a}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Reporting","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/reporting/index.md","filePath":"master/supply-chain/inventories/reporting/index.md","lastUpdated":1793074831000}'),r={name:"master/supply-chain/inventories/reporting/index.md"};function n(i,t,l,h,d,c){return s(),o("div",null,t[0]||(t[0]=[a('<h1 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h1><p>Reports answer two questions: where is my stock right now, and how did it get there? Aureus gives you one page for each question.</p><blockquote><p><strong>In simple words:</strong> Product Quantities shows what you have. Moves History shows what happened.</p></blockquote><p>Open them from <code>Inventory → Reporting</code>.</p><table tabindex="0"><thead><tr><th>Page</th><th>Question it answers</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Locations</strong> (Product Quantities)</td><td>How much is where?</td><td>Check on hand and reserved stock by location, lot or package</td></tr><tr><td><strong>Moves History</strong> (Move Lines)</td><td>What moved and when?</td><td>Trace a product, lot or document</td></tr></tbody></table><h2 id="typical-uses" tabindex="-1">Typical uses <a class="header-anchor" href="#typical-uses" aria-label="Permalink to &quot;Typical uses&quot;">​</a></h2><ul><li>A customer asks if you have 10 units. Check the stock report.</li><li>A quantity looks wrong. Check Moves History for the last moves of that product.</li><li>A lot is recalled. Filter Moves History by the lot number.</li><li>You want to correct a count. Use <a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a>.</li></ul><h2 id="tools-on-both-pages" tabindex="-1">Tools on both pages <a class="header-anchor" href="#tools-on-both-pages" aria-label="Permalink to &quot;Tools on both pages&quot;">​</a></h2><ul><li><strong>Tabs</strong> are saved views such as <strong>Done</strong> or <strong>On Hand</strong>.</li><li><strong>Group by</strong> collapses rows into groups.</li><li><strong>Filters</strong> narrow rows by location, category, package and more.</li><li>The column manager shows or hides columns.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./moves-history.html">Moves history</a></li><li><a href="./stock-report.html">Stock report</a></li><li><a href="./../adjustments/">Adjustments</a></li></ul>',11)]))}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
